cd /home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/inbox/local/items && for f in *.yaml; do st=$(grep -m1 '^status:' $f | sed 's/status: *//'); k=$(grep -m1 '^kind:' $f | sed 's/kind: *//'); [ "$st" = "open" ] && [ "$k" = "conversation" ] && echo "${f%.yaml}"; done | tr '\n' ' '; echo; python3 -c "
import yaml,glob
for i in ['I-0474','I-0475','I-0476']:
    try: d=yaml.safe_load(open(i+'.yaml'))
    except: continue
    m=d.get('metadata') or {}
    print('=====',i,d.get('kind'),'| started_by',m.get('started_by'),'| participants',m.get('participants'))
    print((d.get('body') or '')[:500])"

